def matching_failures(query: str, sector: str, limit: int = 6) -> list[FailRecord]:
    low = f" {query.lower()} {sector} "
    scored: list[tuple[int, FailRecord]] = []
    for rec in FAILURES:
        score = sum(1 for kw in rec["keywords"] if kw in low)
        if score:
            scored.append((score, rec))
    scored.sort(key=lambda x: (-x[0], x[1]["name"]))
    if not scored:
        # No domain analog matched: return a cross-domain spread of instructive deaths
        names = ["MoviePass", "Fast (checkout, one-click)", "Hopin", "Wish (ContextLogic)", "Homejoy", "Chegg's AI cliff (ongoing decline)"]
        return [r for r in FAILURES if r["name"] in names][:limit]
    return [rec for _, rec in scored[:limit]]
